selected.compute:
options=read('/input/options')
result=None
for count in reversed(range(goal['min_count'],goal['max_count']+1)):
    for group in combinations(options,count):
        proposal=[row['id'] for row in group]
        if valid(proposal):
            result=proposal
            break
    if result is not None:
        break

selected.effects:
if result is None:
    status('report')
else:
    if not exists('/output/selection'):
        write('/output/selection',result)
    delivery=receipt('report')
    if delivery=='unattempted' or delivery=='failure':
        send('report','team',result)
    if exists('/tmp/cache'):
        delete('/tmp/cache')
